# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ALLAH\'A İMAN VE YÜCE ALLAH\'IN SIFATLARI (SIFAT-I İLAHİYYE)</text>\n  <rect x="25" y="45" width="310" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">ZATİ SIFATLAR (ALLAH\'IN ZATINA ÖZGÜ)</text>\n  <text x="42" y="94" font-size="11" font-weight="bold" fill="#1e3a8a">1. Vücud: Var olması (varlığı zorunludur)</text>\n  <text x="42" y="116" font-size="11" font-weight="bold" fill="#1e3a8a">2. Kıdem: Ezeli olması (başlangıcı olmaması)</text>\n  <text x="42" y="138" font-size="11" font-weight="bold" fill="#1e3a8a">3. Beka: Ebedi olması (sonu olmaması)</text>\n  <text x="42" y="160" font-size="11" font-weight="bold" fill="#1e3a8a">4. Vahdaniyet: Bir ve tek olması (Tevhid)</text>\n  <text x="42" y="182" font-size="11" font-weight="bold" fill="#1e3a8a">5. Muhalefetün lil-havadis: Sonradan yaratılan</text>\n  <text x="52" y="198" font-size="10.5" fill="#1d4ed8">varlıklardan hiçbirine benzememesi</text>\n  <text x="42" y="220" font-size="11" font-weight="bold" fill="#1e3a8a">6. Kıyam bi-nefsihi: Varlığının kendinden olması</text>\n  <rect x="355" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">SUBUTİ SIFATLAR (SINIRSIZ VE KUSURSUZ)</text>\n  <text x="372" y="94" font-size="11" font-weight="bold" fill="#14532d">• Hayat: Diri ve canlı olması, hayat vermesi</text>\n  <text x="372" y="114" font-size="11" font-weight="bold" fill="#14532d">• İlim: Gizli ve açık her şeyi eksiksiz bilmesi</text>\n  <text x="372" y="134" font-size="11" font-weight="bold" fill="#14532d">• Semi: Her şeyi işitmesi (duyması)</text>\n  <text x="372" y="154" font-size="11" font-weight="bold" fill="#14532d">• Basar: Her şeyi engelsiz biçimde görmesi</text>\n  <text x="372" y="174" font-size="11" font-weight="bold" fill="#14532d">• İrade: Dilemesi, bir şeyin olmasını tercih etmesi</text>\n  <text x="372" y="194" font-size="11" font-weight="bold" fill="#14532d">• Kudret: Her şeye gücünün yetmesi</text>\n  <text x="372" y="214" font-size="11" font-weight="bold" fill="#14532d">• Kelam: Konuşması, peygamberlere vahiy göndermesi</text>\n  <text x="372" y="232" font-size="11" font-weight="bold" fill="#14532d">• Tekvin: Yoktan var etmesi, yaratması ("Ol!" emri)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MELEKLERE İMAN: DÖRT BÜYÜK MELEK VE DİĞER MELEKLER</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">DÖRT BÜYÜK MELEK VE GÖREVLERİ</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#78350f">• Cebrail (Cibrîl / Rûhu\'l-Kudüs / Rûhu\'l-Emîn):</text>\n  <text x="45" y="112" font-size="10.5" fill="#92400e">Allah\'tan aldığı vahiyleri peygamberlere ileten vahiy meleğidir.</text>\n  <text x="35" y="136" font-size="11" font-weight="bold" fill="#78350f">• Mikâil:</text>\n  <text x="45" y="152" font-size="10.5" fill="#92400e">Tabiat olaylarını (yağmur, rüzgâr) ve rızıkları idare eden melektir.</text>\n  <text x="35" y="176" font-size="11" font-weight="bold" fill="#78350f">• İsrafil:</text>\n  <text x="45" y="192" font-size="10.5" fill="#92400e">Kıyametin kopması ve yeniden diriliş için Sûr\'a üfleyecek melektir.</text>\n  <text x="35" y="216" font-size="11" font-weight="bold" fill="#78350f">• Azrail (Melekü\'l-Mevt):</text>\n  <text x="45" y="232" font-size="10.5" fill="#92400e">Eceli gelenlerin ruhunu teslim almakla görevli ölüm meleğidir.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#7e22ce">DİĞER MELEKLER VE GENEL ÖZELLİKLERİ</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#581c87">• Kirâmen Kâtibîn (Yazıcı Melekler):</text>\n  <text x="385" y="112" font-size="10.5" fill="#6b21a8">İnsanın sağında ve solunda iyilik ve kötülüklerini kaydeder.</text>\n  <text x="375" y="136" font-size="11" font-weight="bold" fill="#581c87">• Münker ve Nekir (Sorgu Melekleri):</text>\n  <text x="385" y="152" font-size="10.5" fill="#6b21a8">Vefat eden kişiyi kabirde sorguya çeken meleklerdir.</text>\n  <text x="375" y="176" font-size="11" font-weight="bold" fill="#581c87">• Hafaza (Koruyucu) · Rıdvan ve Mâlik · Hamele-i Arş</text>\n  <text x="375" y="200" font-size="10.5" fill="#6b21a8">• Nurdan yaratılmışlardır; yemez, içmez, evlenmez, günah</text>\n  <text x="383" y="216" font-size="10.5" fill="#6b21a8">işlemezler ve gaybı kendi başlarına bilemezler.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">İLAHİ KİTAPLARA İMAN: SUHUF (SAYFALAR) VE DÖRT BÜYÜK KİTAP</text>\n  <rect x="20" y="45" width="290" height="195" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="165" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#0e7490">100 SUHUF (SAHİFELER)</text>\n  <text x="38" y="98" font-size="11.5" font-weight="bold" fill="#155e75">• Hz. Âdem (as): 10 Sahife</text>\n  <text x="38" y="124" font-size="11.5" font-weight="bold" fill="#155e75">• Hz. Şît (as): 50 Sahife</text>\n  <text x="38" y="150" font-size="11.5" font-weight="bold" fill="#155e75">• Hz. İdris (as): 30 Sahife</text>\n  <text x="38" y="176" font-size="11.5" font-weight="bold" fill="#155e75">• Hz. İbrahim (as): 10 Sahife</text>\n  <text x="38" y="206" font-size="10.5" fill="#0e7490">Not: Suhuf, belirli dönem ve toplumların</text>\n  <text x="38" y="222" font-size="10.5" fill="#0e7490">ihtiyacına göre indirilen kısa risalelerdir.</text>\n  <rect x="325" y="45" width="355" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="502" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b91c1c">DÖRT BÜYÜK İLAHİ KİTAP VE ÖZELLİKLERİ</text>\n  <text x="340" y="96" font-size="11" font-weight="bold" fill="#7f1d1d">1. Tevrat → Hz. Musa (as) (İbranice, İsrailoğulları)</text>\n  <text x="340" y="120" font-size="11" font-weight="bold" fill="#7f1d1d">2. Zebur → Hz. Davut (as) (Mezmurlar, öğüt ve dualar)</text>\n  <text x="340" y="144" font-size="11" font-weight="bold" fill="#7f1d1d">3. İncil → Hz. İsa (as) (Müjde, sevgi ve ahlak esasları)</text>\n  <text x="340" y="168" font-size="11" font-weight="bold" fill="#15803d">4. Kur\'an-ı Kerim → Hz. Muhammed (sav)</text>\n  <text x="350" y="188" font-size="10.5" fill="#166534">• Son ilahi kitaptır, hükmü kıyamete kadar geçerlidir.</text>\n  <text x="350" y="206" font-size="10.5" fill="#166534">• Tahrif edilmeden (değiştirilmeden) günümüze ulaşmıştır.</text>\n  <text x="350" y="224" font-size="10.5" fill="#166534">• İsimleri: el-Furkan, el-Hüda, en-Nur, eş-Şifa, ez-Zikir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
